                if (root.Position - walk).Magnitude > 3 then
                    ch:PivotTo(CFrame.new(walk + Vector3.new(0, 3, 0)) * look.Rotation)
                    task.wait(0.3)
                end
            end
            local kicked = false
            pcall(function() kicked = GuiService:GetErrorMessage() ~= "" end)
            if kicked then FL.tpMsg = __T["Kicked after teleport"]
            elseif off > 12 then FL.tpMsg = __T["Pulled back, try again in a few seconds"]
            else FL.tpMsg = "Teleported to " .. kind:lower() .. " (" .. math.floor((goal - start).Magnitude) .. " studs)" end
            LOG("tp", kind, math.floor((goal - start).Magnitude), "off", math.floor(off), tostring(kicked))
        end)
        if not ok then FL.tpMsg = __T["Teleport failed"] LOG("tperr", err) end
        FL.moving = false
    end)
end
