FL.pesp = {}
function FL.updatePlayers()
    local want = on("f_pesp")
    for plr, h in pairs(FL.pesp) do
        if not want or not plr.Parent or not plr.Character or h.Adornee ~= plr.Character then pcall(function() h:Destroy() end) FL.pesp[plr] = nil end
    end
    if not want then return end
    local root = hrp()
    local ok, parent = pcall(function() return (gethui and gethui()) or game:GetService("CoreGui") end)
    for _, p in ipairs(Players:GetPlayers()) do
        local ch = p.Character
        local head = ch and ch:FindFirstChild("Head")
        if p ~= lp and ch and head then
            local beast = ch:FindFirstChild("Hammer") ~= nil
            local frozen = false
            pcall(function() local ts = p:FindFirstChild("TempPlayerStatsModule") frozen = ts and ts:FindFirstChild("Captured") and ts.Captured.Value == true end)
            local color = beast and Color3.fromRGB(255, 60, 60) or (frozen and Color3.fromRGB(120, 200, 255) or Color3.fromRGB(255, 230, 90))
            local h = FL.pesp[p]
            if not h then
                h = Instance.new("Highlight")
                h.DepthMode, h.FillTransparency, h.OutlineTransparency = Enum.HighlightDepthMode.AlwaysOnTop, 0.65, 0
                h.Adornee = ch
                local bb = Instance.new("BillboardGui")
                bb.Name, bb.Size, bb.AlwaysOnTop, bb.StudsOffset = "Tag", UDim2.fromOffset(160, 22), true, Vector3.new(0, 2.6, 0)
                local tl = Instance.new("TextLabel")
                tl.Name, tl.Size, tl.BackgroundTransparency, tl.TextStrokeTransparency, tl.Font, tl.TextScaled = "T", UDim2.fromScale(1, 1), 1, 0.3, Enum.Font.GothamBold, true
                tl.Parent = bb
                bb.Parent = h
                h.Parent = ok and parent or lp.PlayerGui
                FL.pesp[p] = h
            end
            h.FillColor, h.OutlineColor = color, color
            local bb = h:FindFirstChild("Tag")
            if bb then
                bb.Adornee = head
                local d = root and math.floor((head.Position - root.Position).Magnitude) or 0
                bb.T.TextColor3 = color
                bb.T.Text = (beast and "BEAST " or (frozen and "FROZEN " or "")) .. p.DisplayName .. " [" .. d .. "]"
            end
        end
    end
end
