local H = { cfg = nil, shop = nil, lastClaim = 0, bought = {} }
H.GAMES = {
    { name = "Sell Lemons", place = 79268393072444, badge = 115007543086503, auto = true },
    { name = "PARANORMAL", place = 16426359665, badge = 1337707865569958, auto = true },
    { name = "Flee the Facility", place = 893973440, badge = 1891002643329212, auto = false },
}
function H.data(name)
    local d = lp:FindFirstChild("PlayerGui") and lp.PlayerGui:FindFirstChild("Data")
    local v = d and d:FindFirstChild(name)
    return v and v.Value
end
function H.list(name)
    local s = H.data(name)
    if type(s) ~= "string" then return {} end
    local ok, t = pcall(function() return HttpService:JSONDecode(s) end)
    return ok and type(t) == "table" and t or {}
end
function H.has(t, x) for _, v in ipairs(t) do if v == x or tostring(v) == tostring(x) then return true end end return false end
function H.balance() return (tonumber(H.data("ClaimedCurrency")) or 0) - (tonumber(H.data("SpentCurrency")) or 0) end
function H.day() return tonumber(Workspace:GetAttribute("EventDay")) or 1 end
function H.load()
    if not H.cfg then H.cfg = inThread(function() return require(ReplicatedStorage.Config.CurrencyBadgeConfig) end, 5) end
    if not H.shop then H.shop = inThread(function() return require(ReplicatedStorage.SharedModules.GearShopConfig) end, 5) end
end
function H.unclaimed()
    H.load()
    if type(H.cfg) ~= "table" then return 0 end
    local earned, queue = H.list("EarnedBadges"), H.list("BadgeQueue")
    local claimed, bonus = H.list("ClaimedCurrencyBadges"), H.list("ClaimedBonusBadges")
    local n, day = 0, H.day()
    for id, v in pairs(H.cfg) do
        if type(v) == "table" and (H.has(earned, id) or H.has(queue, id)) then
            local feat = v.featuredDay == day
            if not H.has(claimed, id) or (feat and not H.has(bonus, id)) then n += 1 end
        end
    end
    return n
end
H.pedTried = {}
function H.pedestals()
    local hub = Workspace:FindFirstChild("Evil_Hub")
    local out = {}
    if not hub then return out end
    for _, d in ipairs(hub:GetDescendants()) do
        if d.Name:find("^UGCPedestal_") and d:FindFirstChild("CheckRemote") then out[#out + 1] = d end
    end
    return out
end
function H.claimPedestals()
    local earned, queue = H.list("EarnedBadges"), H.list("BadgeQueue")
    for _, p in ipairs(H.pedestals()) do
        local id = p:GetAttribute("BadgeId")
        local pp = p:FindFirstChildWhichIsA("ProximityPrompt")
        if id and (H.has(earned, id) or H.has(queue, id)) and pp and pp.Enabled and pp.ActionText == "Claim" and not H.pedTried[p] then
            H.pedTried[p] = true
            local ok, a, b = pcall(function() return inThread(function() return p.CheckRemote:InvokeServer() end, 12) end)
            LOG("pedestal", p.Name, tostring(ok), tostring(a), tostring(b))
            if ok and a then say(__T["Claimed a free UGC"]) notify(__T["Claimed a free UGC!"]) end
            task.wait(2)
        end
    end
end
function H.tick()
    if not (lp:FindFirstChild("BadgesLoaded") and H.data("ClaimedCurrency") ~= nil) then S.task = __T["Loading"] return end
    if on("h_claim") and H.unclaimed() > 0 and os.clock() - H.lastClaim > 8 then
        H.lastClaim = os.clock()
        local r = ReplicatedStorage:FindFirstChild("Remotes") and ReplicatedStorage.Remotes:FindFirstChild("ClaimBadgeCurrency")
        if r then pcall(function() r:FireServer() end) say(__T["Claimed badge coins"]) end
        task.wait(3)
    end
    if on("h_ped") then pcall(H.claimPedestals) end
    if on("h_buy") and type(H.shop) == "table" and type(H.shop.UGC) == "table" then
        local owned, day = H.list("OwnedGear"), H.day()
        local items = {}
        for _, it in ipairs(H.shop.UGC) do
            if not it.plusOnly and (it.releaseDay or 99) <= day and not H.has(owned, it.id) and not H.bought[it.id] then items[#items + 1] = it end
        end
        table.sort(items, function(a, b) return (a.releaseDay or 0) < (b.releaseDay or 0) end)
        for _, it in ipairs(items) do
            if H.balance() >= (it.price or math.huge) then
                local rf = ReplicatedStorage.Remotes:FindFirstChild("GearShopBuy")
                local r = rf and inThread(function() return rf:InvokeServer(it.id) end, 12)
                LOG("buy", it.id, tostring(r))
                if r then H.bought[it.id] = true say(__T["Bought "] .. tostring(it.name)) notify(__T["Got UGC: "] .. tostring(it.name)) end
                task.wait(2)
            end
        end
    end
    if F.chain() then
        if H.unclaimed() > 0 then S.task = __T["Claiming badge coins"] return end
        for _, g in ipairs(H.GAMES) do
            if g.auto and not F.hasBadge(g.badge) then
                S.task = __T["Going to "] .. g.name
                if not H.leaving then H.leaving = true task.delay(4, function() if RUNNING and F.chain() then F.join(g.place) end H.leaving = false end) end
                return
            end
        end
        S.task = __T["All supported badges done"]
        F.chain(false)
        pcall(function() Toggles.h_chain:SetValue(false) end)
        notify(__T["All supported badges done!"])
        return
    end
    S.task = __T["Idle"]
end
function H.status()
    H.load()
    local owned = H.list("OwnedGear")
    local names = {}
    if type(H.shop) == "table" and type(H.shop.UGC) == "table" then
        for _, it in ipairs(H.shop.UGC) do if H.has(owned, it.id) then names[#names + 1] = it.name end end
    end
    local lines = {
        __T["Event day: "] .. H.day(),
        __T["Spooky Coins: "] .. H.balance(),
        __T["Unclaimed badges: "] .. H.unclaimed(),
        __T["UGC owned: "] .. (#names > 0 and table.concat(names, ", ") or __T["none yet"]),
    }
    local nxt = tonumber(Workspace:GetAttribute("NextDayTimestamp"))
    if nxt then lines[#lines + 1] = __T["Next day in "] .. eta(nxt - Workspace:GetServerTimeNow()) end
    return table.concat(lines, "\n")
end
function H.next()
    H.load()
    if type(H.shop) ~= "table" or type(H.shop.UGC) ~= "table" then return "" end
    local owned, day = H.list("OwnedGear"), H.day()
    local out = {}
    for _, it in ipairs(H.shop.UGC) do
