        local m = Library.ScreenGui and Library.ScreenGui:FindFirstChild("Main")
        if m then m.AnchorPoint = Vector2.zero m.Position = UDim2.new(0.5, -math.floor(m.AbsoluteSize.X / 2), 0.5, -math.floor(m.AbsoluteSize.Y / 2)) end
    end)
end)
